<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$offer=(int)($_POST['offre_id']??0);$motif=trim((string)($_POST['motif']??''));if($offer&&$motif!==''){$s=$db->prepare('SELECT demande_id FROM offres_devis WHERE id=?');$s->execute([$offer]);$demande=(int)$s->fetchColumn();$db->prepare("INSERT INTO recommandations(demande_id,offre_id,auteur_id,motif,avantages,limites) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE offre_id=VALUES(offre_id),auteur_id=VALUES(auteur_id),motif=VALUES(motif),avantages=VALUES(avantages),limites=VALUES(limites),statut_validation='en_attente',validateur_id=NULL,date_validation=NULL")->execute([$demande,$offer,$_SESSION['user']['id'],$motif,trim((string)($_POST['avantages']??''))?:null,trim((string)($_POST['limites']??''))?:null]);$db->prepare("UPDATE demandes_devis SET statut='recommandee' WHERE id=?")->execute([$demande]);$db->prepare("UPDATE offres_devis SET statut=IF(id=?,'retenue','rejetee') WHERE demande_id=?")->execute([$offer,$demande]);audit('RECOMMANDATION','offre_devis',$offer);flash('success','Recommandation soumise pour validation.');}redirect('recommandations/index.php');}$offers=$db->query("SELECT o.id,o.prime_totale,o.score_global,d.numero_demande,p.nom produit,co.raison_sociale compagnie FROM offres_devis o JOIN demandes_devis d ON d.id=o.demande_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id WHERE d.statut='comparee' ORDER BY d.date_demande DESC,o.score_global DESC")->fetchAll();$rows=$db->query("SELECT r.*,d.numero_demande,o.prime_totale,o.score_global,p.nom produit,co.raison_sociale compagnie FROM recommandations r JOIN demandes_devis d ON d.id=r.demande_id JOIN offres_devis o ON o.id=r.offre_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id ORDER BY r.date_recommandation DESC")->fetchAll();$title='Recommandations';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Recommandations motivées</h1><p class="text-secondary">Sélection, justification et validation</p></div></div><?php if($offers): ?><form method="post" class="card card-body mb-4"><?= csrf_field() ?><h2 class="h5">Nouvelle recommandation</h2><div class="row g-3"><div class="col-md-6"><label class="form-label">Offre *</label><select class="form-select" name="offre_id" required><?php foreach($offers as $o): ?><option value="<?= $o['id'] ?>"><?= e($o['numero_demande'].' · '.$o['compagnie'].' · '.$o['produit'].' · '.number_format((float)$o['prime_totale'],0,',',' ').' FCFA · score '.$o['score_global']) ?></option><?php endforeach ?></select></div><div class="col-md-6"><label class="form-label">Motivation *</label><input class="form-control" name="motif" required placeholder="Meilleur équilibre entre couverture et coût"></div><div class="col-md-6"><label class="form-label">Avantages</label><textarea class="form-control" name="avantages" rows="2"></textarea></div><div class="col-md-6"><label class="form-label">Limites</label><textarea class="form-control" name="limites" rows="2"></textarea></div></div><div class="text-end mt-3"><button class="btn btn-primary">Soumettre</button></div></form><?php endif; ?><div class="card"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Demande</th><th>Offre</th><th>Prime</th><th>Motivation</th><th>Statut</th><th class="text-end">Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['numero_demande']) ?></td><td><strong><?= e($r['produit']) ?></strong><div class="small"><?= e($r['compagnie']) ?></div></td><td><?= number_format((float)$r['prime_totale'],0,',',' ') ?> FCFA</td><td><?= e($r['motif']) ?></td><td><span class="badge text-bg-<?= $r['statut_validation']==='validee'?'success':($r['statut_validation']==='rejetee'?'danger':'warning') ?>"><?= e($r['statut_validation']) ?></span></td><td class="text-end"><?php if($r['statut_validation']==='en_attente'&&in_array($_SESSION['user']['role'],['ADMIN','RESPONSABLE'],true)): ?><a class="btn btn-sm btn-primary" href="validation.php?id=<?= $r['id'] ?>&decision=validee">Valider</a> <a class="btn btn-sm btn-outline-danger" href="validation.php?id=<?= $r['id'] ?>&decision=rejetee">Rejeter</a><?php elseif($r['statut_validation']==='validee'): ?><a class="btn btn-sm btn-success" href="<?= APP_URL ?>/souscriptions/form.php?recommandation_id=<?= $r['id'] ?>">Souscrire</a><?php endif; ?></td></tr><?php endforeach ?></tbody></table></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
